pub fn summarize_results(results: &[TestResult]) -> Summary {
    let mut passed = 0;
    let mut failed = 0;
    let mut not_run = 0;
    for result in results {
        match result.status {
            CaseStatus::Passed => passed += 1,
            CaseStatus::Failed => failed += 1,
            CaseStatus::NotRun => not_run += 1,
        }
    }
    Summary {
        total: results.len(),
        passed,
        failed,
        not_run,
    }
}

